import{_ as h,o as i,c as t,a5 as c}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Product Video Pipeline — đặc tả luồng","description":"","frontmatter":{},"headers":[],"relativePath":"feature/product-video-pipeline/spec.md","filePath":"feature/product-video-pipeline/spec.md"}'),o={name:"feature/product-video-pipeline/spec.md"};function e(g,n,a,l,u,d){return i(),t("div",null,[...n[0]||(n[0]=[c('<h1 id="product-video-pipeline-—-đac-ta-luong" tabindex="-1">Product Video Pipeline — đặc tả luồng <a class="header-anchor" href="#product-video-pipeline-—-đac-ta-luong" aria-label="Permalink to &quot;Product Video Pipeline — đặc tả luồng&quot;">​</a></h1><p>Ngày: 30/10/2026. Trạng thái: đã triển khai code và kiểm chứng local bằng provider/API fixture, clip tổng hợp cùng bộ dựng/editor thật; chưa gọi Veo có tính phí hoặc áp dụng migration vào database đang dùng. User đã chọn ba mẫu review/unboxing/giới thiệu sản phẩm, duyệt kịch bản/chi phí trước khi tạo, dùng credit BrandHub; phí Google chỉ theo dõi nội bộ.</p><h2 id="muc-tieu" tabindex="-1">Mục tiêu <a class="header-anchor" href="#muc-tieu" aria-label="Permalink to &quot;Mục tiêu&quot;">​</a></h2><p>User mô tả video bằng một form. Hệ thống tìm mẫu phù hợp trong kho của dự án, điền thông tin và lập kịch bản 2–3 cảnh. User xem, sửa và duyệt chi phí trước khi tạo. Veo sinh clip cho từng cảnh; bộ dựng dựa trên công nghệ DemoVideo ghép/chỉnh sửa và giao một video hoàn chỉnh.</p><p>Hai hoặc ba clip là các cảnh nguồn của một thành phẩm. Không tự tạo thêm nhiều phương án cho mỗi cảnh. Số cảnh là thông tin có trong kịch bản user duyệt.</p><h2 id="luong-đa-chot" tabindex="-1">Luồng đã chốt <a class="header-anchor" href="#luong-đa-chot" aria-label="Permalink to &quot;Luồng đã chốt&quot;">​</a></h2><ol><li><strong>Nhập form:</strong> ảnh và thông tin sản phẩm; nội dung/yêu cầu; mục đích như review, unboxing hoặc quảng cáo; thời lượng và tỷ lệ khung hình; thông tin chữ/logo/CTA; yêu cầu âm thanh nếu có.</li><li><strong>Tìm mẫu:</strong> bản đầu dùng ba recipe <code>review</code>, <code>unboxing</code>, <code>product_showcase</code>; lọc theo mục đích, ngành, ảnh/tài nguyên hiện có và điều kiện đầu vào. Chọn mẫu có lý do phù hợp; không ghép toàn bộ kho vào prompt hoặc tự viết lại mọi thứ từ đầu. Các tên mẫu là mã của BrandHub, không phải lệnh Google. Kho 50 mục còn lại chỉ là nguồn nghiên cứu cho các đợt sau.</li><li><strong>Lập kịch bản:</strong> 2–3 cảnh có vai trò, nội dung, ảnh tham chiếu, prompt riêng và chỉ dẫn dựng. Dùng chung thông tin nhận dạng sản phẩm, màu sắc, tỷ lệ, phong cách để hạn chế lệch giữa các cảnh. Không hứa loại bỏ hoàn toàn sai lệch của model.</li><li><strong>User duyệt:</strong> hiển thị kịch bản, prompt có thể chỉnh, model/cấu hình, số clip, thời lượng nguồn, thời lượng thành phẩm dự kiến và tổng chi phí dự kiến. Chỉ bấm <strong>Tạo video</strong> mới khởi chạy generation có tính phí. Thay đổi làm tăng chi phí sau bước này phải được user duyệt lại.</li><li><strong>Tạo clip:</strong> lưu và theo dõi từng cảnh; cảnh đã thành công được giữ nguyên. Không tạo lại cả bộ khi chỉ một cảnh lỗi. Không có vòng tự sinh lại vô hạn hoặc âm thầm vượt chi phí đã duyệt.</li><li><strong>Dựng tự động:</strong> dùng kế hoạch dựng để cắt/ghép đúng thứ tự, chỉnh nhịp, chuyển cảnh, chèn chữ/logo/CTA và xử lý âm thanh theo form. Giữ lớp chữ và logo ở hậu kỳ thay vì yêu cầu Veo vẽ chữ chính xác.</li><li><strong>Kiểm tra:</strong> kiểm khả năng giải mã, thời lượng, số frame, âm thanh, vị trí chữ và các điểm nối. Chỉ báo hoàn thành khi có file kết quả hợp lệ. Các kiểm tra tự động không được tuyên bố bảo đảm tuyệt đối hình dáng sản phẩm hoặc chất lượng thẩm mỹ.</li><li><strong>Giao kết quả:</strong> MP4 xem/tải được, kèm bản dựng trong Video Space để tiếp tục chỉnh sửa ở những lớp hỗ trợ. Giữ clip nguồn, kế hoạch và revision; không ghi đè chỉnh sửa tay khi chạy lại.</li></ol><h2 id="vi-du-review-unboxing-chai-nuoc-hoa" tabindex="-1">Ví dụ: review/unboxing chai nước hoa <a class="header-anchor" href="#vi-du-review-unboxing-chai-nuoc-hoa" aria-label="Permalink to &quot;Ví dụ: review/unboxing chai nước hoa&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cảnh</th><th>Vai trò</th><th>Veo tạo</th><th>Bộ dựng bổ sung</th></tr></thead><tbody><tr><td>1</td><td>Mở đầu</td><td>Mở hộp và lấy chai ra</td><td>Nhịp mở đầu, tiếng giấy nếu cần</td></tr><tr><td>2</td><td>Chi tiết</td><td>Cận nắp, cạnh thủy tinh và dung dịch</td><td>Tên/đặc điểm thiết kế do user cung cấp</td></tr><tr><td>3</td><td>Kết</td><td>Toàn cảnh sản phẩm, ánh sáng ổn định</td><td>Logo, CTA và màn kết</td></tr></tbody></table><p>Nếu không có ảnh hộp, form/kịch bản phải làm rõ đó là bao bì giả định và được user chấp nhận, hoặc dùng cảnh khác đủ đầu vào. Không tự khẳng định mùi hương, thành phần, hiệu quả hoặc độ lưu hương từ một ảnh chai.</p><h3 id="đieu-chinh-sau-khi-user-xem-ban-minh-hoa" tabindex="-1">Điều chỉnh sau khi user xem bản minh hoạ <a class="header-anchor" href="#đieu-chinh-sau-khi-user-xem-ban-minh-hoa" aria-label="Permalink to &quot;Điều chỉnh sau khi user xem bản minh hoạ&quot;">​</a></h3><p>User yêu cầu video có hành động mở hộp, lấy sản phẩm ra và review mùi hương. Clip pan/zoom từ một ảnh chỉ kiểm tra bộ dựng, không phải video unboxing/review đã hoàn thành. Không dùng trạng thái “đã tạo video” của fixture làm bằng chứng đã sinh các cảnh Veo thật.</p><ul><li>Kịch bản unboxing20giây gồm3cảnh: mở hộp/lấy chai → trải nghiệm và giới thiệu các nốt hương đã cung cấp → đặt chai vào bố cục kết với CTA. Bản15giây dùng2cảnh, giữ phần trải nghiệm/review trong cảnh2 thay vì bỏ nó để chỉ quay hero.</li><li>Mỗi cảnh phải có hành động cụ thể, góc/chuyển động camera và âm thanh; giữ nhận dạng chai và bao bì đúng tham chiếu. Không yêu cầu tạo phần cứng chai không nhìn thấy trong ảnh. Với nước hoa, có thể dùng giấy thử hương và phản ứng reviewer, không tự suy đoán đầu xịt dưới nắp.</li><li>Thêm <code>reviewScript</code> tuỳ chọn vào form: mỗi dòng là lời review cho một cảnh, đúng2/3dòng theo thời lượng; tối đa18từ/dòng. Lời đọc được user duyệt và đưa vào native audio của Veo, không gọi thêm một dịch vụ TTS trả phí. Có lời đọc thì phải giữ source audio. Không tự bịa lời review từ hình chai.</li><li>User cho phép dùng thông tin <strong>giả lập để test</strong>, ghi rõ là mẫu: AMBER Demo, hương đầu cam bergamot, hương giữa hoa nhài, hương cuối gỗ đàn hương. Không trình bày các nốt hương này như đặc tính suy ra từ ảnh hoặc thuộc sản phẩm thật.</li><li>User xác nhận có credit Google Flow/Google AI Pro hoặc Ultra. Lượt thử có thể tạo cảnh trong Flow theo số dư/quyền tài khoản, sau đó nhập clip thật để dựng. Credit Flow không phải credit BrandHub hoặc số dư API. Kiểm tra model/số output/chi phí thực tế và duyệt trước khi gửi3lượt sinh; không dùng API không chính thức hay vượt hạn mức.</li><li>Việc dùng Flow cho lượt thử không tự chứng minh pipeline API đã hoạt động. Hiện cấu hình mới còn disabled, chưa có Cloud Project và Mongo journal. Không hứa video chuyển động thật đã có khi chỉ có kịch bản hoặc clip dựng từ ảnh.</li></ul><h2 id="mac-đinh-đe-xuat-đe-giu-pham-vi-gon" tabindex="-1">Mặc định đề xuất để giữ phạm vi gọn <a class="header-anchor" href="#mac-đinh-đe-xuat-đe-giu-pham-vi-gon" aria-label="Permalink to &quot;Mặc định đề xuất để giữ phạm vi gọn&quot;">​</a></h2><ul><li>Thời lượng bản đầu đề xuất cho user chọn 15 hoặc 20 giây: tương ứng lập kế hoạch hai hoặc ba clip nguồn 8 giây theo API hiện tại, rồi cắt/dựng về độ dài đã duyệt. Không cho nhập thời lượng vượt khả năng nguồn và không tự kéo chậm/lặp cảnh để bù. Mở rộng video dài hơn cần thay đổi số cảnh/cách tạo và báo giá trước.</li><li>Một thành phẩm, 2–3 cảnh, một lượt sinh cho mỗi cảnh. Số cảnh phụ thuộc thời lượng và mẫu; không mặc định mọi yêu cầu đều phải sinh ba clip.</li><li>Một form chung, hiện thêm trường đầu vào cần thiết theo mẫu; thông tin thương hiệu đã có thì dùng lại theo quyền của workspace.</li><li>Kết quả có hai thao tác chính: tải MP4 và mở trong Video Space.</li><li>Chỉ chèn thông tin sản phẩm/giá/CTA được cung cấp hoặc đã duyệt; thiếu thì bỏ trống hoặc hỏi bổ sung.</li><li>Âm thanh bám yêu cầu: giữ tiếng Veo phù hợp; nhạc/SFX/giọng đọc là các lớp riêng. Bản đầu không tự gọi dịch vụ giọng đọc trả phí chưa được cấu hình và chọn rõ.</li><li>Nguồn nhạc/SFX đề xuất: kho tài nguyên gốc đã duyệt của Video Space hoặc tệp user cung cấp, kèm điều kiện sử dụng. Không mở thêm dịch vụ tìm nhạc hoặc sinh nhạc trả phí. Nếu cần một giọng đọc xuyên suốt mà chưa có nguồn đã chọn, báo thiếu đầu vào thay vì tự coi là đã hỗ trợ.</li><li>Khi cảnh hỏng, giữ các cảnh thành công và hiển thị lựa chọn thử lại cảnh đó kèm chi phí tăng thêm. Lỗi dựng dùng lại nguồn để dựng lại, không tự gọi Veo lần nữa.</li><li>Nếu hiệu ứng DemoVideo không ánh xạ thành lớp chỉnh được trong Video Space, lưu nguồn/kế hoạch và đánh dấu phần đã render thành media; không giả vờ đó là đối tượng 3D hoặc lớp gốc có thể sửa trực tiếp.</li></ul><h2 id="hien-trang-đa-đoi-chieu" tabindex="-1">Hiện trạng đã đối chiếu <a class="header-anchor" href="#hien-trang-đa-đoi-chieu" aria-label="Permalink to &quot;Hiện trạng đã đối chiếu&quot;">​</a></h2><ul><li>Xác minh tài liệu Google ngày 30/10/2026: các model Veo 3.1 Preview trên Gemini API đã ngừng ngày 22/10/2026. Bản triển khai này giữ Veo bằng GA trên Google Cloud (model <code>veo-3.1-generate-001</code>, có thể cấu hình Fast GA), dùng project/location/ADC riêng; không tự đổi sang Gemini Omni. Nguồn: <a href="https://ai.google.dev/gemini-api/docs/video" target="_blank" rel="noreferrer">https://ai.google.dev/gemini-api/docs/video</a> và <a href="https://docs.cloud.google.com/gemini-enterprise-agent-platform/models/veo/3-1-generate" target="_blank" rel="noreferrer">https://docs.cloud.google.com/gemini-enterprise-agent-platform/models/veo/3-1-generate</a> . Cấu hình/quota/billing thật phải sẵn sàng trước lượt tính phí; không coi API key Gemini hiện có là đủ cho đường GA.</li><li>BrandHub AI có Veo provider và job cho một clip; đầu vào có prompt, tỷ lệ, ảnh tham chiếu và template. Có mẫu ba phần tại <code>app/utils/video_templates.py</code>, nhưng chưa có điều phối đầy đủ cho luồng thành phẩm này.</li><li>Kho nghiên cứu có 50 mục/10 nhóm tại <code>video-editor-lab/docs/veo-product-video/catalog.json</code>. Đây mới là mô tả/nguồn tham khảo, chưa phải 50 prompt runtime đã kiểm chứng. Cần chuyển các mẫu phù hợp thành template có biến và điều kiện đầu vào; giữ ID/nguồn.</li><li>Editor Video Space đã được tích hợp ở web. AI dựng tự động bằng DemoVideo chưa được nối vào luồng sản xuất này.</li><li>Nguồn DemoVideo: <code>F:/self/DemoVideo</code>, quy trình chính <code>docs/video-edit/SKILL.md</code>, sổ lỗi <code>tools/edit/LOI_DA_GAP.md</code>. Tái sử dụng phần cần của FFmpeg/HyperFrames và kế hoạch dựng; không sửa dự án DemoVideo gốc, không sao chép credential, profile trình duyệt, dữ liệu phim hoặc môi trường cục bộ.</li><li>Skill là hướng dẫn và bộ công cụ, không tự trở thành một API chạy nền. Cần lớp điều phối, thực thi và theo dõi tiến độ trong hệ thống.</li><li>Dùng các thành phần có điều kiện phù hợp với sản phẩm thương mại; không mang workflow SeeCut-VN PolyForm Noncommercial vào runtime thương mại. Giữ giấy phép của thành phần/tài nguyên thực dùng.</li></ul><h2 id="chi-phi-loi-va-quyen-truy-cap" tabindex="-1">Chi phí, lỗi và quyền truy cập <a class="header-anchor" href="#chi-phi-loi-va-quyen-truy-cap" aria-label="Permalink to &quot;Chi phí, lỗi và quyền truy cập&quot;">​</a></h2><ul><li>Phân biệt credit nội bộ BrandHub với phí Google. Báo chi phí dự kiến cho toàn bộ cảnh và các dịch vụ đã chọn trước generation; không quy đổi tùy tiện credit Flow thành số dư API.</li><li>Với bản mẫu thử qua tài khoản Google Flow của user, credit Pro/Ultra chỉ dùng trong Flow; đây không phải bằng chứng đường API BrandHub đã được cấu hình hoặc chạy thật. Kiểm tra model, số output và tổng credit thực tế rồi xin duyệt lượt sinh. Nếu công cụ chưa kết nối được phiên trình duyệt đã đăng nhập, nói rõ giới hạn và hướng dẫn thao tác trực tiếp; không vượt chặn đăng nhập hoặc sao chép cookie.</li><li>User xem và sử dụng credit BrandHub theo cấu hình giá hiện có. Phí Google/API được ghi nhận nội bộ, không hiển thị như khoản thu USD bổ sung cho user và không đưa giá vốn vào payload frontend. Không tự đặt tỷ lệ quy đổi hoặc một cơ chế thanh toán USD mới.</li><li>Việc Google đã tính phí một clip thành công không được diễn đạt như khoản có thể tự hoàn từ Google khi bước dựng phía sau lỗi. Chính sách credit nội bộ phải tách riêng và được ghi rõ.</li><li>Mỗi sản xuất/cảnh có ID và trạng thái lưu được; bấm lặp hoặc tải lại trang không được tạo lại lượt Veo ngoài ý muốn. Lưu tiến độ để tiếp tục từ phần đã có.</li><li>Ảnh tham chiếu cần cho job chưa gửi được lưu riêng tư theo từng lượt với giới hạn kích thước; khởi động lại phải tiếp tục được cả job đang chờ gửi và job đã có operation. Dữ liệu render có logo cũng phải khôi phục được, không chỉ render không logo.</li><li>Chỉ owner đúng workspace được mở/tiếp tục sản xuất và bản dựng, dùng lại quyền và storage/quota hiện có. Không đưa API key ra trình duyệt.</li><li>Kế hoạch do AI đề xuất phải có cấu trúc và được kiểm tra; không chạy Python, JavaScript, shell hoặc tham số lệnh tùy ý do model trả về. Media và đường dẫn được phân giải từ ID đã kiểm quyền.</li><li>Không commit/push hoặc thay đổi DB/cloud trong giai đoạn đặc tả này.</li></ul><h2 id="ui-va-trang-thai" tabindex="-1">UI và trạng thái <a class="header-anchor" href="#ui-va-trang-thai" aria-label="Permalink to &quot;UI và trạng thái&quot;">​</a></h2><ul><li>Các trạng thái cần thể hiện: nhập form; đang tìm mẫu/lập kịch bản; cần bổ sung đầu vào; sẵn sàng duyệt; đang tạo từng cảnh; cần thử lại một cảnh; đang dựng/kiểm tra; hoàn thành; lỗi giữ nguyên nguồn.</li><li>Namespace i18n đề xuất <code>productVideo</code>: <code>title</code>, <code>brief</code>, <code>assets</code>, <code>goal</code>, <code>style</code>, <code>duration</code>, <code>aspectRatio</code>, <code>audio</code>, <code>storyboard</code>, <code>scene</code>, <code>prompt</code>, <code>missingInputs</code>, <code>estimatedCost</code>, <code>generate</code>, <code>retryScene</code>, <code>additionalCost</code>, <code>generating</code>, <code>editing</code>, <code>validating</code>, <code>download</code>, <code>openEditor</code>, <code>failed</code>, <code>sourcesRetained</code>. Thêm song song vi/en khi làm UI.</li><li>Dùng UI/theme tokens hiện có, kiểm tra light/dark và hiển thị tiến độ từng bước. Không để nguyên tên key hoặc thuật ngữ backend trong giao diện.</li></ul><h2 id="hop-đong-du-lieu-nghiep-vu-đe-buoc-lap-ke-hoach-ky-thuat-su-dung" tabindex="-1">Hợp đồng dữ liệu nghiệp vụ để bước lập kế hoạch kỹ thuật sử dụng <a class="header-anchor" href="#hop-đong-du-lieu-nghiep-vu-đe-buoc-lap-ke-hoach-ky-thuat-su-dung" aria-label="Permalink to &quot;Hợp đồng dữ liệu nghiệp vụ để bước lập kế hoạch kỹ thuật sử dụng&quot;">​</a></h2><ul><li><strong>Brief:</strong> mục đích, yêu cầu gốc, thông tin sản phẩm đã xác nhận, các asset ID, thời lượng/tỷ lệ, yêu cầu chữ và âm thanh.</li><li><strong>Kịch bản có phiên bản:</strong> mã mẫu và lý do chọn, số cảnh, vai trò/prompt/ảnh tham chiếu của từng cảnh, thời lượng/cấu hình, kế hoạch dựng và báo giá dự kiến.</li><li><strong>Lượt sản xuất:</strong> tham chiếu đúng phiên bản kịch bản/chi phí user đã duyệt, ID từng job Veo và media kết quả, trạng thái dựng/QC, MP4 cuối và ID bản dựng Video Space.</li><li>Routes, lưu trữ, adapter DemoVideo và cách chạy job sẽ được quyết định trong <code>plan.md</code> theo code thực tế. Các mục trên không phải endpoint đã tồn tại.</li></ul><h2 id="đieu-kien-hoan-thanh-va-kiem-chung-can-co" tabindex="-1">Điều kiện hoàn thành và kiểm chứng cần có <a class="header-anchor" href="#đieu-kien-hoan-thanh-va-kiem-chung-can-co" aria-label="Permalink to &quot;Điều kiện hoàn thành và kiểm chứng cần có&quot;">​</a></h2><p>Quan sát bản mẫu Flow thật ngày 30/10: clip giao diện ghi 8 giây nhưng file tải xuống có 190 khung hình ở24fps (~7,92 giây). Bước dựng phải kiểm tra đủ khung hình thực sự được kịch bản sử dụng; bản20giây dùng168khung/cảnh vẫn hợp lệ. Không lặp/đóng băng để giả đủ nguồn; cảnh dùng192khung vẫn phải bị từ chối nếu nguồn chỉ có190.</p><p>Chưa coi luồng này là đã chạy chỉ vì có template hoặc script dựng. Cần chứng minh form → chọn mẫu → user duyệt → các clip → dựng → MP4 và mở lại bản dựng. Kiểm tra thêm việc bấm lặp, cảnh lỗi, chỉ dựng lại, thiếu ảnh hộp, thông tin sản phẩm không đủ, lệch quyền workspace, chi phí tăng khi thử lại, i18n/theme và bảo toàn sửa tay. Dùng fixture trước; lượt Veo trả phí chỉ thực hiện theo cấu hình/ngân sách được giao.</p><h2 id="ngoai-pham-vi-ban-đau" tabindex="-1">Ngoài phạm vi bản đầu <a class="header-anchor" href="#ngoai-pham-vi-ban-đau" aria-label="Permalink to &quot;Ngoài phạm vi bản đầu&quot;">​</a></h2><p>Tự động đăng mạng xã hội, sinh hàng loạt phương án quảng cáo, thay người/khẩu hình, khôi phục các lớp/đối tượng đã dính trong MP4, tự thử lại generation vô hạn, hoặc tuyên bố mọi kỹ thuật trong catalog đã được kiểm chứng bằng video thật.</p><h2 id="ra-soat-đe-lap-ke-hoach" tabindex="-1">Rà soát để lập kế hoạch <a class="header-anchor" href="#ra-soat-đe-lap-ke-hoach" aria-label="Permalink to &quot;Rà soát để lập kế hoạch&quot;">​</a></h2><p>Đã có lượt rà soát độc lập đặc tả và user đã trả lời hai điểm còn mở:</p><ol><li>Chỉ ba mẫu review/unboxing/giới thiệu sản phẩm cho bản đầu.</li><li>User dùng credit BrandHub; phí Google theo dõi nội bộ.</li></ol><p>Giới hạn thời lượng 15/20 giây và dùng kho âm thanh hiện có là lựa chọn triển khai được đề xuất để bám 2–3 clip nguồn 8 giây và giữ phạm vi gọn. Hợp đồng giữ/trừ/hoàn credit sẽ dùng cơ chế tài chính hiện có và được ghi cụ thể trong kế hoạch trước khi viết code.</p>',32)])])}const m=h(o,[["render",e]]);export{p as __pageData,m as default};
